<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
$o=getopt('',['company:','operator:','backups']);$company=filter_var($o['company']??null,FILTER_VALIDATE_INT);$operator=filter_var($o['operator']??null,FILTER_VALIDATE_INT);if(!$company||!$operator){fwrite(STDERR,"Usage: php bin/run-business-operations.php --company=ID --operator=SERVICE_USER_ID [--backups]\n");exit(2);}
\Dotenv\Dotenv::createImmutable(dirname(__DIR__))->safeLoad();$app=\Sentinel\Core\Application::create(dirname(__DIR__))->bootstrap();$name=isset($o['backups'])?'backups':'business-operations';$authorised=false;$started=gmdate('Y-m-d H:i:s');
try{$ctx=$app->runtimeContext();$ctx->setTenantId($company);$ctx->setUser((string)$operator);if(!$app->database()->fetch("SELECT user_id FROM users WHERE company_id=:company AND user_id=:user AND status='ACTIVE'",['company'=>$company,'user'=>$operator]))throw new \RuntimeException('Invalid operator.');$p=new \Sentinel\Repositories\PermissionRepository($app->database(),$ctx);if($p->userHasPermission((string)$operator,'site_scope.restricted'))throw new \RuntimeException('Use an unrestricted tenant worker.');$app->container()->make('authorization_service')->requirePermission((string)$operator,isset($o['backups'])?'backups.run':'business_ops.run');$authorised=true;$result=isset($o['backups'])?$app->container()->make('encrypted_backup_service')->runDue():$app->container()->make('business_reminder_service')->tick();$state=!empty($result['failed'])?'FAILED':'OK';$app->database()->execute('INSERT INTO worker_runs(company_id,worker_name,started_at,finished_at,state,summary) VALUES(:company,:name,:start,:end,:state,:summary)',['company'=>$company,'name'=>$name,'start'=>$started,'end'=>gmdate('Y-m-d H:i:s'),'state'=>$state,'summary'=>$state==='OK'?'Business operations / recovery evaluation completed.':'Backup failed; review recovery configuration and receipts.']);echo json_encode($result,JSON_THROW_ON_ERROR).PHP_EOL;if($state==='FAILED')exit(1);}catch(\Throwable){if($app->database()->inTransaction())$app->database()->rollBack();if($authorised)try{$app->container()->make('control_room_service')->recordWorkerFailure($name);}catch(\Throwable){}fwrite(STDERR,"Business operations worker failed. Review its restricted configuration and readiness receipts.\n");exit(1);}
